def remove_example_rows(df):

    df = df.dropna(how="all").copy()

    if "Remarks" in df.columns:

        mask = (
            df["Remarks"]
            .astype(str)
            .str.contains(
                "Example row",
                case=False,
                na=False
            )
        )

        df = df[~mask]

    return df


